def solve(chunks):
    if chunks is None:
        return ""
    if isinstance(chunks, str):
        return chunks
    try:
        iterable = list(chunks)
    except TypeError:
        return ""

    parts = []
    for chunk in iterable:
        if chunk is not None:
            parts.append(str(chunk))
    return "".join(parts)

